-- Parameters must be provided by the trusted owner AFTER approval. Never client settings.
-- Required settings: macrogoal.pair_enable_approved, pair_source_release_ready,
-- pair_service_route_ready, pair_truncate_scope_approved,
-- pair_member_a, pair_member_b. All approval/readiness settings must equal 'true'.
DO $activate$
DECLARE a uuid;b uuid;prior_a uuid;prior_b uuid;
BEGIN
 IF current_user<>'postgres' OR current_setting('macrogoal.pair_enable_approved',true) IS DISTINCT FROM 'true'
 OR current_setting('macrogoal.pair_source_release_ready',true) IS DISTINCT FROM 'true'
 OR current_setting('macrogoal.pair_service_route_ready',true) IS DISTINCT FROM 'true'
 OR current_setting('macrogoal.pair_truncate_scope_approved',true) IS DISTINCT FROM 'true' THEN
 RAISE EXCEPTION 'explicit pair activation, source/service readiness and broader TRUNCATE approval required'; END IF;
 a:=nullif(current_setting('macrogoal.pair_member_a',true),'')::uuid;
 b:=nullif(current_setting('macrogoal.pair_member_b',true),'')::uuid;
 IF a IS NULL OR b IS NULL OR a=b THEN RAISE EXCEPTION 'two distinct approved member IDs required'; END IF;
 IF (SELECT count(*) FROM public.users WHERE id IN(a,b))<>2 THEN RAISE EXCEPTION 'pair profiles missing'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('macrogoal:community-rollout',0));
 SELECT member_a,member_b INTO prior_a,prior_b FROM privacy_private.community_rollout WHERE singleton AND mode='CLOSED' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'rollout must be CLOSED'; END IF;
 IF prior_a IS NOT NULL AND (least(a,b)<>least(prior_a,prior_b) OR greatest(a,b)<>greatest(prior_a,prior_b)) THEN
  RAISE EXCEPTION 'pair change requires uninstall and separately reviewed configuration'; END IF;
 -- Require an empty exact-pair trial relationship baseline. No pre-existing row
 -- will be removed, relabeled, imported as acceptance, or silently restored.
 IF EXISTS(SELECT 1 FROM public.social_follows WHERE follower_id IN(a,b) AND following_id IN(a,b) AND follower_id<>following_id)
 OR EXISTS(SELECT 1 FROM public.blocked_users WHERE blocker_id IN(a,b) AND blocked_id IN(a,b) AND blocker_id<>blocked_id)
 OR EXISTS(SELECT 1 FROM public.community_blocks WHERE blocker_id IN(a,b) AND blocked_id IN(a,b) AND blocker_id<>blocked_id)
 OR EXISTS(SELECT 1 FROM privacy_private.follow_inbox_cursors WHERE owner_id IN(a,b)) THEN
  RAISE EXCEPTION 'preexisting pair relationships or owner cursors require separate preserved-baseline plan'; END IF;
 -- No legacy edge or pre-existing request can be imported as owner acceptance.
 IF EXISTS(SELECT 1 FROM public.follow_requests WHERE requester_id IN(a,b) AND owner_id IN(a,b)) THEN
  RAISE EXCEPTION 'pair request rows must be reviewed/cleaned before first activation'; END IF;
 UPDATE privacy_private.community_rollout SET mode='PAIR',member_a=a,member_b=b WHERE singleton;
END $activate$;
